code='''from collections import deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                y, x = queue.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        queue.append((ny, nx))
            result.append((color, cells))
    return result


def _marker_l(cells, h, w):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    for pr in (r0, r1):
        for pc in (c0, c1):
            expected = {(pr, c) for c in range(c0, c1 + 1)}
            expected |= {(r, pc) for r in range(r0, r1 + 1)}
            if cells != expected:
                continue
            # The two free ends of the L reach the grid edges.
            horizontal_edge = c0 == 0 if pc == c1 else c1 == w - 1
            vertical_edge = r0 == 0 if pr == r1 else r1 == h - 1
            if horizontal_edge and vertical_edge:
                return pr, pc
    return None


def _shape(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    base = {(r - min(rs), c - min(cs)) for r, c in cells}
    forms = []
    for reflect in (False, True):
        pts = {(r, -c if reflect else c) for r, c in base}
        for _ in range(4):
            rmin = min(r for r, c in pts)
            cmin = min(c for r, c in pts)
            forms.append(tuple(sorted((r - rmin, c - cmin) for r, c in pts)))
            pts = {(c, -r) for r, c in pts}
    return min(forms)


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    objects = _components(grid, background)

    marker = None
    for i, (color, cells) in enumerate(objects):
        corner = _marker_l(cells, h, w)
        if corner is not None:
            marker = (i, color, cells, corner)
            break
    if marker is None:
        return out

    marker_i, marker_color, marker_cells, (pr, pc) = marker
    rows = range(0, pr) if pr == h - 1 else range(pr + 1, h)
    cols = range(0, pc) if pc == w - 1 else range(pc + 1, w)
    inside_bounds = (set(rows), set(cols))

    inside = []
    outside = []
    for i, (color, cells) in enumerate(objects):
        if i == marker_i:
            continue
        in_box = all(r in inside_bounds[0] and c in inside_bounds[1] for r, c in cells)
        (inside if in_box else outside).append((i, color, cells))

    matches = []
    for ii, _, icells in inside:
        key = _shape(icells)
        for oi, _, ocells in outside:
            if key == _shape(ocells):
                matches.append((oi, ocells))
    if matches:
        # The duplicate outside the L-bounded corner is the one to recolor.
        _, cells = matches[0]
        for r, c in cells:
            out[r][c] = marker_color
    return out
'''
